/** `SyntaxVisitor`: a method per node kind, each falling back to [defaultVisit]. */
open class RedSyntaxVisitor {
    open fun visit(node: RedNode?) {
        node?.accept(this)
    }
    open fun defaultVisit(node: RedNode) {}
    open fun visitToken(token: RedToken) = defaultVisit(token)
    open fun visitRazorDocument(node: RazorDocumentSyntax) = defaultVisit(node)
    open fun visitRazorCommentBlock(node: RazorCommentBlockSyntax) = defaultVisit(node)
    open fun visitRazorMetaCode(node: RazorMetaCodeSyntax) = defaultVisit(node)
    open fun visitGenericBlock(node: GenericBlockSyntax) = defaultVisit(node)
    open fun visitUnclassifiedTextLiteral(node: UnclassifiedTextLiteralSyntax) = defaultVisit(node)
    open fun visitMarkupBlock(node: MarkupBlockSyntax) = defaultVisit(node)
    open fun visitMarkupTransition(node: MarkupTransitionSyntax) = defaultVisit(node)
    open fun visitMarkupTextLiteral(node: MarkupTextLiteralSyntax) = defaultVisit(node)
    open fun visitMarkupEphemeralTextLiteral(node: MarkupEphemeralTextLiteralSyntax) = defaultVisit(node)
    open fun visitMarkupCommentBlock(node: MarkupCommentBlockSyntax) = defaultVisit(node)
    open fun visitMarkupMinimizedAttributeBlock(node: MarkupMinimizedAttributeBlockSyntax) = defaultVisit(node)
    open fun visitMarkupAttributeBlock(node: MarkupAttributeBlockSyntax) = defaultVisit(node)
    open fun visitMarkupMiscAttributeContent(node: MarkupMiscAttributeContentSyntax) = defaultVisit(node)
    open fun visitMarkupLiteralAttributeValue(node: MarkupLiteralAttributeValueSyntax) = defaultVisit(node)
    open fun visitMarkupDynamicAttributeValue(node: MarkupDynamicAttributeValueSyntax) = defaultVisit(node)
    open fun visitMarkupElement(node: MarkupElementSyntax) = defaultVisit(node)
    open fun visitMarkupStartTag(node: MarkupStartTagSyntax) = defaultVisit(node)
    open fun visitMarkupEndTag(node: MarkupEndTagSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperElement(node: MarkupTagHelperElementSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperStartTag(node: MarkupTagHelperStartTagSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperEndTag(node: MarkupTagHelperEndTagSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperAttribute(node: MarkupTagHelperAttributeSyntax) = defaultVisit(node)
    open fun visitMarkupMinimizedTagHelperAttribute(node: MarkupMinimizedTagHelperAttributeSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperAttributeValue(node: MarkupTagHelperAttributeValueSyntax) = defaultVisit(node)
    open fun visitMarkupTagHelperDirectiveAttribute(node: MarkupTagHelperDirectiveAttributeSyntax) = defaultVisit(node)
    open fun visitMarkupMinimizedTagHelperDirectiveAttribute(node: MarkupMinimizedTagHelperDirectiveAttributeSyntax) = defaultVisit(node)
    open fun visitCSharpCodeBlock(node: CSharpCodeBlockSyntax) = defaultVisit(node)
    open fun visitCSharpTransition(node: CSharpTransitionSyntax) = defaultVisit(node)
    open fun visitCSharpStatementLiteral(node: CSharpStatementLiteralSyntax) = defaultVisit(node)
    open fun visitCSharpExpressionLiteral(node: CSharpExpressionLiteralSyntax) = defaultVisit(node)
    open fun visitCSharpEphemeralTextLiteral(node: CSharpEphemeralTextLiteralSyntax) = defaultVisit(node)
    open fun visitCSharpTemplateBlock(node: CSharpTemplateBlockSyntax) = defaultVisit(node)
    open fun visitCSharpStatement(node: CSharpStatementSyntax) = defaultVisit(node)
    open fun visitCSharpStatementBody(node: CSharpStatementBodySyntax) = defaultVisit(node)
    open fun visitCSharpExplicitExpression(node: CSharpExplicitExpressionSyntax) = defaultVisit(node)
    open fun visitCSharpExplicitExpressionBody(node: CSharpExplicitExpressionBodySyntax) = defaultVisit(node)
    open fun visitCSharpImplicitExpression(node: CSharpImplicitExpressionSyntax) = defaultVisit(node)
    open fun visitCSharpImplicitExpressionBody(node: CSharpImplicitExpressionBodySyntax) = defaultVisit(node)
    open fun visitRazorDirective(node: RazorDirectiveSyntax) = defaultVisit(node)
    open fun visitRazorUsingDirective(node: RazorUsingDirectiveSyntax) = defaultVisit(node)
    open fun visitRazorDocumentationDirective(node: RazorDocumentationDirectiveSyntax) = defaultVisit(node)
    open fun visitRazorDirectiveBody(node: RazorDirectiveBodySyntax) = defaultVisit(node)
}

/** `SyntaxWalker`: visits the children (nodes and tokens) by default. */
open class RedSyntaxWalker : RedSyntaxVisitor() {
    override fun defaultVisit(node: RedNode) {
        for (child in node.childNodesAndTokens()) visit(child)
    }
}

/** The red node of a green one. */
object RedNodes {
    fun create(green: RazorNode, parent: RedNode?, position: Int): RedNode = when (green) {
        is RazorToken -> RedToken(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorDocumentSyntax -> RazorDocumentSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorCommentBlockSyntax -> RazorCommentBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorMetaCodeSyntax -> RazorMetaCodeSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.GenericBlockSyntax -> GenericBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.UnclassifiedTextLiteralSyntax -> UnclassifiedTextLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupBlockSyntax -> MarkupBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTransitionSyntax -> MarkupTransitionSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTextLiteralSyntax -> MarkupTextLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupEphemeralTextLiteralSyntax -> MarkupEphemeralTextLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupCommentBlockSyntax -> MarkupCommentBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupMinimizedAttributeBlockSyntax -> MarkupMinimizedAttributeBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupAttributeBlockSyntax -> MarkupAttributeBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupMiscAttributeContentSyntax -> MarkupMiscAttributeContentSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupLiteralAttributeValueSyntax -> MarkupLiteralAttributeValueSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupDynamicAttributeValueSyntax -> MarkupDynamicAttributeValueSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupElementSyntax -> MarkupElementSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupStartTagSyntax -> MarkupStartTagSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupEndTagSyntax -> MarkupEndTagSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperElementSyntax -> MarkupTagHelperElementSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperStartTagSyntax -> MarkupTagHelperStartTagSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperEndTagSyntax -> MarkupTagHelperEndTagSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperAttributeSyntax -> MarkupTagHelperAttributeSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupMinimizedTagHelperAttributeSyntax -> MarkupMinimizedTagHelperAttributeSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperAttributeValueSyntax -> MarkupTagHelperAttributeValueSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupTagHelperDirectiveAttributeSyntax -> MarkupTagHelperDirectiveAttributeSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.MarkupMinimizedTagHelperDirectiveAttributeSyntax -> MarkupMinimizedTagHelperDirectiveAttributeSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpCodeBlockSyntax -> CSharpCodeBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpTransitionSyntax -> CSharpTransitionSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpStatementLiteralSyntax -> CSharpStatementLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpExpressionLiteralSyntax -> CSharpExpressionLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpEphemeralTextLiteralSyntax -> CSharpEphemeralTextLiteralSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpTemplateBlockSyntax -> CSharpTemplateBlockSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpStatementSyntax -> CSharpStatementSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpStatementBodySyntax -> CSharpStatementBodySyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpExplicitExpressionSyntax -> CSharpExplicitExpressionSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpExplicitExpressionBodySyntax -> CSharpExplicitExpressionBodySyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpImplicitExpressionSyntax -> CSharpImplicitExpressionSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.CSharpImplicitExpressionBodySyntax -> CSharpImplicitExpressionBodySyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorDirectiveSyntax -> RazorDirectiveSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorUsingDirectiveSyntax -> RazorUsingDirectiveSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorDocumentationDirectiveSyntax -> RazorDocumentationDirectiveSyntax(green, parent, position)
        is io.github.dotnetsupport.razor.lang.syntax.RazorDirectiveBodySyntax -> RazorDirectiveBodySyntax(green, parent, position)
        else -> throw IllegalArgumentException("no red node for ${green.kind}")
    }
}
